import React from 'react';

interface PromptInputProps {
  value: string;
  onChange: (val: string) => void;
  onProcess: () => void;
  disabled: boolean;
}

const PromptInput: React.FC<PromptInputProps> = ({ value, onChange, onProcess, disabled }) => {
  const promptCount = value.split(';').map(p => p.trim()).filter(Boolean).length;

  return (
    <div className="space-y-6">
      <div className="relative group">
        <textarea
          name="bulk_prompt_input"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          placeholder="Cyberpunk city sunset; A futuristic bioluminescent forest; A minimalist red coffee cup on a marble table; Abstract data flowing through space..."
          className="w-full min-h-[200px] p-6 bg-slate-900 rounded-2xl border-2 border-slate-700 focus:border-yellow-400/50 focus:ring-4 focus:ring-yellow-400/10 transition-all text-lg placeholder:text-slate-600 outline-none resize-none"
          disabled={disabled}
        />
        <div className="absolute bottom-4 right-4 flex items-center gap-3">
          {promptCount > 0 && (
            <span className="px-3 py-1 bg-slate-800 rounded-lg text-xs font-mono text-slate-400 border border-slate-700">
              {promptCount} {promptCount === 1 ? 'Prompt' : 'Prompts'} Detected
            </span>
          )}
        </div>
      </div>

      <div className="flex flex-col sm:flex-row gap-4">
        <button
          onClick={onProcess}
          disabled={disabled || !value.trim()}
          className="flex-1 px-8 py-5 bg-yellow-400 hover:bg-yellow-300 disabled:bg-slate-700 disabled:text-slate-500 text-slate-900 font-bold rounded-2xl transition-all active:scale-[0.98] shadow-xl shadow-yellow-500/10 flex items-center justify-center gap-3 text-xl group"
        >
          {disabled ? (
            <>
              <i className="fa-solid fa-spinner fa-spin"></i>
              Powering Engines...
            </>
          ) : (
            <>
              <i className="fa-solid fa-wand-magic-sparkles group-hover:rotate-12 transition-transform"></i>
              Ignite Bulk Generation
            </>
          )}
        </button>

        <button
          onClick={() => onChange('')}
          disabled={disabled || !value.trim()}
          className="px-6 py-5 bg-slate-800 hover:bg-slate-700 disabled:opacity-50 text-white font-semibold rounded-2xl transition-all border border-slate-700"
        >
          Clear
        </button>
      </div>
    </div>
  );
};

export default PromptInput;

import React from 'react';
