            <p className="text-xs text-slate-500 break-words line-clamp-2">{result.error}</p>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-4 text-slate-500">
            <div className="relative">
              <div className="w-16 h-16 border-4 border-slate-800 border-t-yellow-400 rounded-full animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-xs font-bold text-slate-600">#{result.index}</span>
              </div>
            </div>
            <p className="text-sm font-medium animate-pulse">Drafting Pixels...</p>
          </div>
        )}
      </div>

      <div className="p-4 flex flex-col flex-1 bg-slate-900/50">
        <span className="text-[10px] uppercase tracking-wider font-bold text-yellow-500/80 mb-1">
          Prompt #{result.index}
        </span>
        <p className="text-sm text-slate-300 font-medium line-clamp-3 leading-relaxed">
          {result.prompt}
        </p>
      </div>
    </div>
  );
};

export default ImageCard;

import React from 'react';
import { GenerationResult } from '../types';

interface StatusOverlayProps {
  results: GenerationResult[];
}

const StatusOverlay: React.FC<StatusOverlayProps> = ({ results }) => {
  const completed = results.filter(r => r.status === 'completed').length;
  const failed = results.filter(r => r.status === 'failed').length;
  const total = results.length;
  const progress = total > 0 ? ((completed + failed) / total) * 100 : 0;

  return (
    <div className="fixed bottom-8 left-1/2 -translate-x-1/2 w-[90%] max-w-lg z-50">
      <div className="bg-slate-900/90 backdrop-blur-xl border border-slate-700/50 rounded-2xl p-4 shadow-2xl space-y-3 ring-1 ring-white/10">
        <div className="flex items-center justify-between text-sm">
          <div className="flex items-center gap-2">
            <i className="fa-solid fa-circle-notch fa-spin text-yellow-400"></i>
            <span className="font-bold text-slate-200">Processing Batch</span>
          </div>
          <span className="font-mono text-slate-400">
            {completed + failed} / {total} Completed
          </span>
        </div>

        <div className="h-3 w-full bg-slate-800 rounded-full overflow-hidden border border-slate-700/50">
          <div 
            className="h-full bg-gradient-to-r from-yellow-600 to-yellow-300 transition-all duration-500 ease-out"
            style={{ width: `${progress}%` }}
          ></div>
        </div>

        {failed > 0 && (
          <p className="text-[10px] text-red-400/80 font-bold uppercase tracking-widest text-center">
            {failed} image{failed !== 1 ? 's' : ''} encountered errors
          </p>
        )}
      </div>
    </div>
  );
};

export default StatusOverlay;

