  aspectRatio: string;
  setAspectRatio: (val: string) => void;
  imageSize: string;
  setImageSize: (val: string) => void;
  referenceImages: ReferenceImage[];
  setReferenceImages: (imgs: ReferenceImage[]) => void;
}

const PromptInput: React.FC<PromptInputProps> = ({ 
  basePrompt,
  setBasePrompt,
  value, 
  onChange, 
  onProcess, 
  disabled,
  aspectRatio,
  setAspectRatio,
  imageSize,
  setImageSize,
  referenceImages,
  setReferenceImages
}) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const promptCount = value.split(';').map(p => p.trim()).filter(Boolean).length;

  const aspectRatios = [
    { label: '1:1', value: '1:1', icon: 'fa-square' },
    { label: '4:3', value: '4:3', icon: 'fa-rectangle-list' },
    { label: '16:9', value: '16:9', icon: 'fa-rectangle-ad' },
    { label: '3:4', value: '3:4', icon: 'fa-mobile-screen' },
    { label: '9:16', value: '9:16', icon: 'fa-mobile' },
