          <i className="fa-solid fa-layer-group text-yellow-500/80"></i>
          Bulk Prompts (Tách bằng dấu chấm phẩy ;)
        </label>
        <div className="relative group">
          <textarea
            name="bulk_prompt_input"
            value={value}
            onChange={(e) => onChange(e.target.value)}
            placeholder="Cyberpunk city sunset; A futuristic bioluminescent forest; A minimalist red coffee cup on a marble table..."
            className="w-full min-h-[180px] p-6 bg-slate-900 rounded-2xl border-2 border-slate-700 focus:border-yellow-400/50 focus:ring-4 focus:ring-yellow-400/10 transition-all text-lg placeholder:text-slate-600 outline-none resize-none"
            disabled={disabled}
          />
          <div className="absolute bottom-4 right-4 flex items-center gap-3">
            {promptCount > 0 && (
              <span className="px-3 py-1 bg-slate-800 rounded-lg text-xs font-mono text-slate-400 border border-slate-700">
                {promptCount} {promptCount === 1 ? 'Prompt' : 'Prompts'} Detected
              </span>
            )}
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 py-2">
        {/* Reference Image Upload */}
        <div className="space-y-3 lg:col-span-1">
