              <i className="fa-solid fa-plus text-lg"></i>
              <span className="text-[8px] mt-0.5 font-bold uppercase">Thêm</span>
            </button>

            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={handleFileChange} 
              className="hidden" 
              accept="image/*"
              multiple
            />
          </div>
          {referenceImages.length === 0 && (
            <div className="text-[10px] text-slate-500">
              Optional: Upload multiple images to guide consistency.
            </div>
