          </label>
          <div className="flex flex-wrap gap-2">
            {qualities.map((q) => (
              <button
                key={q.value}
                onClick={() => setImageSize(q.value)}
                disabled={disabled}
                className={`px-3 py-2 rounded-xl text-xs font-bold transition-all border ${
                  imageSize === q.value 
                    ? 'bg-yellow-400 border-yellow-400 text-slate-900 shadow-lg shadow-yellow-400/20 scale-105' 
                    : 'bg-slate-900 border-slate-700 text-slate-400 hover:border-slate-500'
                }`}
              >
                {q.label}
              </button>
            ))}
          </div>
        </div>
      </div>

      <div className="flex flex-col sm:flex-row gap-4 pt-4 border-t border-slate-800">
        <button
          onClick={onProcess}
          disabled={disabled || !value.trim()}
          className="flex-1 px-8 py-5 bg-yellow-400 hover:bg-yellow-300 disabled:bg-slate-700 disabled:text-slate-500 text-slate-900 font-bold rounded-2xl transition-all active:scale-[0.98] shadow-xl shadow-yellow-500/10 flex items-center justify-center gap-3 text-xl group"
        >
