import { GoogleGenAI } from "@google/genai";
import { ReferenceImage } from "./types";

const IMAGE_MODEL = 'gemini-3-pro-image-preview';
const TEXT_MODEL = 'gemini-3-flash-preview';

export async function generateImage(
  prompt: string, 
  aspectRatio: string = "1:1", 
  imageSize: string = "1K",
  referenceImages: ReferenceImage[] = []
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const parts: any[] = [];

    referenceImages.forEach((img) => {
      parts.push({
        inlineData: {
          data: img.data,
          mimeType: img.mimeType,
        },
      });
    });

    parts.push({ text: prompt });

    const response = await ai.models.generateContent({
      model: IMAGE_MODEL,
      contents: { parts },
      config: {
        imageConfig: {
          aspectRatio: aspectRatio as any,
          imageSize: imageSize as any
        }
      },
    });

    if (!response.candidates?.[0]?.content?.parts) {
      throw new Error("Invalid response format from API");
    }

    for (const part of response.candidates[0].content.parts) {
      if (part.inlineData) {
        return `data:image/png;base64,${part.inlineData.data}`;
      }
    }

    throw new Error("No image data found in response");
  } catch (error: any) {
    if (error.message?.includes("Requested entity was not found")) {
      throw new Error("KEY_RESET_REQUIRED");
    }
    throw error;
  }
}

/**
 * Generates a cinematic motion prompt based on the visual content of the image.
 */
export async function generateMotionPrompt(
  base64Image: string,
  originalPrompt: string
): Promise<string> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // Strip the data URL prefix if present
  const data = base64Image.includes('base64,') 
    ? base64Image.split('base64,')[1] 
    : base64Image;

  const systemInstruction = `You are a world-class Director of Photography. 
  Your task is to write a concise "Motion Prompt" (15-25 words) for a video AI tool (like Luma, Runway, or Kling) based on the image provided.

  CRITICAL RULES:
  1. ONLY specify camera movements (e.g., "Slow cinematic pan from left to right", "Tracking shot moving forward", "Subtle tilt up").
  2. NEVER suggest zooming into or focusing specifically on a character's face.
  3. Ensure the motion is suitable for B-roll or POV shots.
  4. Use professional cinematography terms: handheld, crane shot, orbital, slider, dolly.
  5. Output ONLY the motion prompt text. No preamble.`;

  try {
    const response = await ai.models.generateContent({
      model: TEXT_MODEL,
      contents: [
        {
          parts: [
            {
              inlineData: {
                data: data,
                mimeType: "image/png",
              },
            },
            { text: `Original Prompt: ${originalPrompt}. Describe the best cinematic camera movement for this scene.` },
          ],
        },
      ],
      config: {
        systemInstruction,
        temperature: 0.7,
      },
    });

    return response.text?.trim() || "Slow cinematic pan to the right, steady camera movement.";
  } catch (error) {
    console.error("Failed to generate motion prompt:", error);
    return "Slow cinematic pan to the right, steady camera movement.";
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import { GenerationResult, ReferenceImage } from './types';
import { generateImage, generateMotionPrompt } from './geminiService';
import Header from './components/Header';
import PromptInput from './components/PromptInput';
import ImageCard from './components/ImageCard';
import StatusOverlay from './components/StatusOverlay';

declare global {
  interface AIStudio {
    hasSelectedApiKey: () => Promise<boolean>;
    openSelectKey: () => Promise<void>;
  }
  interface Window {
    aistudio?: AIStudio;
  }
}

const App: React.FC = () => {
  const [basePrompt, setBasePrompt] = useState('');
  const [bulkPromptInput, setBulkPromptInput] = useState('');
  const [results, setResults] = useState<GenerationResult[]>([]);
  const [isProcessing, setIsProcessing] = useState(false);
  const [hasKey, setHasKey] = useState<boolean | null>(null);

  const [aspectRatio, setAspectRatio] = useState('1:1');
  const [imageSize, setImageSize] = useState('1K');
  const [referenceImages, setReferenceImages] = useState<ReferenceImage[]>([]);

  useEffect(() => {
    const checkKey = async () => {
      try {
        const selected = await window.aistudio?.hasSelectedApiKey();
        setHasKey(selected ?? false);
      } catch (e) {
        setHasKey(false);
      }
    };
    checkKey();
  }, []);

  const handleSelectKey = async () => {
    await window.aistudio?.openSelectKey();
    setHasKey(true);
  };

  const handleDownloadAll = () => {
    const completed = results.filter(r => r.status === 'completed' && r.imageUrl);
    completed.forEach((res, i) => {
      setTimeout(() => {
        const link = document.createElement('a');
        link.href = res.imageUrl!;
        link.download = `nano-banana-${res.index}.png`;
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
      }, i * 250);
    });
  };

  const constructPrompt = (specific: string) => {
    if (!basePrompt.trim()) return specific;
    return `${basePrompt.trim()}, ${specific.trim()}`;
  };

  const regenerateSingle = async (id: string) => {
    const target = results.find(r => r.id === id);
    if (!target) return;

    setResults(prev => prev.map(item => 
      item.id === id ? { ...item, status: 'processing', error: undefined, motionPrompt: undefined } : item
    ));

    try {
      const fullPrompt = constructPrompt(target.prompt);
      const imageUrl = await generateImage(fullPrompt, aspectRatio, imageSize, referenceImages);

      // Update with image first
      setResults(prev => prev.map(item => 
        item.id === id ? { ...item, imageUrl, status: 'completed' } : item
      ));

      // Then generate motion prompt
      const motionPrompt = await generateMotionPrompt(imageUrl, fullPrompt);
      setResults(prev => prev.map(item => 
        item.id === id ? { ...item, motionPrompt } : item
      ));

    } catch (error: any) {
      if (error.message === "KEY_RESET_REQUIRED") {
        setHasKey(false);
      }
      setResults(prev => prev.map(item => 
        item.id === id ? { ...item, error: error.message || "Failed to generate", status: 'failed' } : item
      ));
    }
  };

  const processBulkInput = useCallback(async () => {
    if (!bulkPromptInput.trim()) return;

    setIsProcessing(true);

    const prompts = bulkPromptInput
      .split(';')
      .map(p => p.trim())
      .filter(Boolean);

    const initialResults: GenerationResult[] = prompts.map((p, i) => ({
      id: Math.random().toString(36).substr(2, 9),
      prompt: p,
      index: i + 1,
      status: 'pending' as const,
    }));

    setResults(initialResults);

    const tasks = initialResults.map(async (res) => {
      setResults(prev => prev.map(item => 
        item.id === res.id ? { ...item, status: 'processing' as const } : item
      ));

      try {
        const fullPrompt = constructPrompt(res.prompt);
        const imageUrl = await generateImage(fullPrompt, aspectRatio, imageSize, referenceImages);

        setResults(prev => prev.map(item => 
          item.id === res.id ? { ...item, imageUrl, status: 'completed' as const } : item
        ));

        // Generate motion prompt asynchronously after image success
        const motionPrompt = await generateMotionPrompt(imageUrl, fullPrompt);
        setResults(prev => prev.map(item => 
          item.id === res.id ? { ...item, motionPrompt } : item
        ));

      } catch (error: any) {
        if (error.message === "KEY_RESET_REQUIRED") {
          setHasKey(false);
          setResults(prev => prev.map(item => 
            item.id === res.id ? { ...item, error: "API Key requires reset.", status: 'failed' as const } : item
          ));
        } else {
          setResults(prev => prev.map(item => 
            item.id === res.id ? { ...item, error: error.message || "Failed to generate", status: 'failed' as const } : item
          ));
        }
      }
    });

    await Promise.allSettled(tasks);
    setIsProcessing(false);
  }, [bulkPromptInput, basePrompt, aspectRatio, imageSize, referenceImages]);

  const completedCount = results.filter(r => r.status === 'completed').length;

  if (hasKey === false) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center p-6 text-center space-y-8">
        <div className="w-24 h-24 bg-yellow-400 rounded-full flex items-center justify-center shadow-lg shadow-yellow-500/50">
          <i className="fa-solid fa-key text-slate-900 text-4xl"></i>
        </div>
        <div className="max-w-md space-y-4">
          <h1 className="text-4xl font-black text-white">Project Setup Required</h1>
          <p className="text-slate-400 text-lg leading-relaxed">
            The Gemini 3 Pro Image model requires a personal API key from a paid GCP project. 
            Please select your key to begin bulk image generation.
          </p>
          <div className="pt-4">
            <button 
              onClick={handleSelectKey}
              className="px-8 py-4 bg-yellow-400 hover:bg-yellow-300 text-slate-900 font-bold rounded-xl transition-all active:scale-95 shadow-lg shadow-yellow-500/20"
            >
              Select Paid API Key
            </button>
          </div>
          <p className="text-xs text-slate-500">
            Learn more about <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="underline hover:text-yellow-400">billing and quotas</a>.
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className="max-w-7xl mx-auto px-4 py-12 md:px-8">
      <Header />

      <main className="space-y-12">
        <section className="bg-slate-800/50 backdrop-blur-md rounded-3xl p-6 md:p-8 border border-slate-700/50 shadow-2xl">
          <PromptInput 
            basePrompt={basePrompt}
            setBasePrompt={setBasePrompt}
            value={bulkPromptInput} 
            onChange={setBulkPromptInput} 
            onProcess={processBulkInput}
            disabled={isProcessing}
            aspectRatio={aspectRatio}
            setAspectRatio={setAspectRatio}
            imageSize={imageSize}
            setImageSize={setImageSize}
            referenceImages={referenceImages}
            setReferenceImages={setReferenceImages}
          />
        </section>

        {results.length > 0 && (
          <section className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-700">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 border-b border-slate-800 pb-4">
              <h2 className="text-2xl font-bold flex items-center gap-3">
                <i className="fa-solid fa-layer-group text-yellow-400"></i>
                Generated Batch ({results.length})
              </h2>

              {completedCount > 0 && (
                <button
                  onClick={handleDownloadAll}
                  className="flex items-center justify-center gap-2 px-6 py-2 bg-slate-800 hover:bg-slate-700 text-white font-bold rounded-xl border border-slate-700 transition-all hover:border-yellow-400/50 shadow-lg active:scale-95"
                >
                  <i className="fa-solid fa-file-arrow-down text-yellow-400"></i>
                  Tải xuống tất cả ({completedCount})
                </button>
              )}
            </div>

            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
              {results.map((result) => (
                <ImageCard 
                  key={result.id} 
                  result={result} 
                  onRegenerate={() => regenerateSingle(result.id)}
                />
              ))}
            </div>
          </section>
        )}
      </main>

      {isProcessing && <StatusOverlay results={results} />}
    </div>
  );
};

export default App;

import React, { useState } from 'react';
