  return (
    <div className="group bg-slate-900 rounded-2xl border border-slate-800 overflow-hidden flex flex-col shadow-lg transition-all hover:border-yellow-400/30">
      <div className="relative aspect-square bg-slate-950 flex items-center justify-center">
        {result.status === 'completed' && result.imageUrl ? (
          <>
            <img 
              src={result.imageUrl} 
              alt={result.prompt} 
              className="w-full h-full object-cover animate-in fade-in duration-1000"
            />
            <div className="absolute top-4 right-4 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              <a 
                href={result.imageUrl} 
                download={`prompt-${result.index}.png`}
                className="p-2 bg-black/60 backdrop-blur-md rounded-lg text-white hover:bg-yellow-400 hover:text-slate-900 shadow-xl transition-colors"
                title="Download Image"
              >
                <i className="fa-solid fa-download"></i>
              </a>
            </div>
          </>
