          <div className="p-6 text-center space-y-2">
            <i className="fa-solid fa-circle-exclamation text-red-400 text-3xl"></i>
            <p className="text-red-400 text-sm font-medium">Generation Failed</p>
            <p className="text-xs text-slate-500 break-words line-clamp-2">{result.error}</p>
          </div>
        ) : (
          <div className="flex flex-col items-center gap-4 text-slate-500">
            <div className="relative">
              <div className="w-16 h-16 border-4 border-slate-800 border-t-yellow-400 rounded-full animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <span className="text-xs font-bold text-slate-600">#{result.index}</span>
              </div>
            </div>
            <p className="text-sm font-medium animate-pulse">Drafting Pixels...</p>
          </div>
        )}
      </div>

      <div className="p-4 flex flex-col flex-1 bg-slate-900/50 space-y-4">
        {/* Prompt Section */}
        <div className="flex-1">
          <span className="text-[10px] uppercase tracking-wider font-bold text-yellow-500/80 mb-1 block">
            Image Prompt #{result.index}
          </span>
          <p className="text-sm text-slate-300 font-medium line-clamp-2 leading-relaxed">
            {result.prompt}
          </p>
        </div>

        {/* Motion Prompt Section */}
        {result.status === 'completed' && (
          <div className="pt-3 border-t border-slate-800/50 animate-in fade-in slide-in-from-bottom-2 duration-500">
            <div className="flex items-center justify-between mb-1.5">
              <span className="text-[10px] uppercase tracking-wider font-bold text-cyan-400 flex items-center gap-1.5">
                <i className="fa-solid fa-clapperboard"></i>
                Motion Prompt
              </span>
              {result.motionPrompt && (
                <button 
                  onClick={handleCopyMotion}
                  className={`text-[10px] font-bold px-2 py-0.5 rounded transition-all ${
                    copied ? 'bg-green-500 text-white' : 'bg-slate-800 text-slate-400 hover:text-white'
                  }`}
                >
                  {copied ? <><i className="fa-solid fa-check mr-1"></i>Copied</> : <><i className="fa-solid fa-copy mr-1"></i>Copy</>}
                </button>
              )}
            </div>

            {result.motionPrompt ? (
              <p className="text-[11px] text-slate-400 leading-relaxed italic bg-black/20 p-2 rounded-lg border border-slate-800/30">
                "{result.motionPrompt}"
              </p>
            ) : (
              <div className="flex items-center gap-2 text-[11px] text-slate-500 italic py-1">
                <i className="fa-solid fa-wand-sparkles fa-spin text-cyan-500/50"></i>
                Analyzing for motion...
              </div>
            )}
          </div>
        )}

        <div className="flex gap-2">
          <button
            onClick={onRegenerate}
            disabled={isProcessing}
            className={`flex-1 flex items-center justify-center gap-2 py-2 px-3 rounded-xl text-xs font-bold transition-all border ${
              isProcessing
                ? 'bg-slate-800 border-slate-700 text-slate-600 cursor-not-allowed'
                : 'bg-slate-800 hover:bg-slate-700 border-slate-700 text-slate-300 hover:text-yellow-400 hover:border-yellow-400/50 active:scale-95'
            }`}
          >
            <i className={`fa-solid fa-arrows-rotate ${isProcessing ? 'fa-spin' : ''}`}></i>
            Regenerate
          </button>
        </div>
      </div>
    </div>
  );
};

